const LOCAL_DATA_DIR = join(process.cwd(), '.tuzhong-data')
const USER_METADATA_FILE = join(LOCAL_DATA_DIR, 'user-metadata.json')

function ensureDataFolder() {
  if (!existsSync(LOCAL_DATA_DIR)) {
    mkdirSync(LOCAL_DATA_DIR, { recursive: true })
  }
}

function loadUserMetadata() {
  if (!existsSync(USER_METADATA_FILE)) {
    return {
      vipStatus: 'free',
      vipExpireDate: '',
      firstGeneratedNovelId: '',
      totalGeneratedCount: 0,
      createdNovelIds: [] as string[]
    }
  }
  try {
    const fileRawText = readFileSync(USER_METADATA_FILE, 'utf-8')
    const parsed = JSON.parse(fileRawText)
    return {
      vipStatus: parsed.vipStatus || 'free',
      vipExpireDate: parsed.vipExpireDate || '',
      firstGeneratedNovelId: parsed.firstGeneratedNovelId || '',
      totalGeneratedCount: parsed.totalGeneratedCount || 0,
      createdNovelIds: Array.isArray(parsed.createdNovelIds) ? parsed.createdNovelIds : []
    }
  } catch {
    return {
      vipStatus: 'free',
      vipExpireDate: '',
      firstGeneratedNovelId: '',
      totalGeneratedCount: 0,
      createdNovelIds: [] as string[]
    }
  }
}

function saveUserMetadata(metadata: any) {
  ensureDataFolder()
  writeFileSync(USER_METADATA_FILE, JSON.stringify(metadata, null, 2), 'utf-8')
}

// 🔥 BUG-12修复：从设定中心 setting-types.json 动态读取金手指/体系类型
// 确保世界观/金手指/大纲环节的力量体系从设定中心取值，而非硬编码
interface SettingTypeItem {
  id: string
  name: string
  category: string
  description?: string
  order: number
  // 金手指类型详细字段（与阶段3世界构建-金手指组对齐）
  coreFunction?: string
  triggerCondition?: string    // 触发条件（原 specificAbilities）
  limitations?: string
  growthPath?: string
  // 兼容字段：旧数据迁移用
  specificAbilities?: string
  // 体系类型详细字段（与阶段3世界构建-力量体系组对齐）
  realmSystem?: string
  cultivationMethod?: string   // 修炼方式
  restraintRelation?: string   // 克制关系
}
interface SettingTypesData {
  abilityTypes: SettingTypeItem[]
  systemTypes: SettingTypeItem[]
}
// 设定中心类型文件缓存（基于mtime）
let _settingTypesCache: { data: SettingTypesData; mtime: number } | null = null
function loadSettingTypesFromCenter(): SettingTypesData {
  const typesFile = join(LOCAL_DATA_DIR, 'setting-types.json')
  if (!existsSync(typesFile)) {
    return { abilityTypes: [], systemTypes: [] }
  }
  try {
    var fileMtime = 0
    try {
      var fsStat = statSync(typesFile)
      fileMtime = fsStat.mtimeMs
    } catch {}
    // 基于mtime缓存
    if (_settingTypesCache && _settingTypesCache.mtime === fileMtime) {
      return _settingTypesCache.data
    }
    const raw = readFileSync(typesFile, 'utf-8')
    const parsed = JSON.parse(raw)
    const data: SettingTypesData = {
      abilityTypes: Array.isArray(parsed.abilityTypes) ? parsed.abilityTypes : [],
      systemTypes: Array.isArray(parsed.systemTypes) ? parsed.systemTypes : [],
    }
    _settingTypesCache = { data, mtime: fileMtime }
    return data
  } catch {
    return { abilityTypes: [], systemTypes: [] }
  }
}

// 根据体系类型名称从设定中心获取 realmSystem（12级等级）
function getRealmSystemFromCenter(sysTypeName: string): string {
  if (!sysTypeName) return ''
  const types = loadSettingTypesFromCenter()
  const found = types.systemTypes.find((t) => t.name === sysTypeName)
  if (!found?.realmSystem) return ''
  // 🔥 BUG-12修复：统一分隔符为→，兼容设定中心数据中可能使用的\n、>、；等分隔符
  var _realm = found.realmSystem
  _realm = _realm.replace(/\r\n/g, '\n').replace(/\r/g, '\n')
  _realm = _realm.replace(/\n/g, '→')
  _realm = _realm.replace(/；/g, '→').replace(/;/g, '→')
  _realm = _realm.replace(/→+/g, '→')
  _realm = _realm.replace(/^→|→$/g, '')
  return _realm
}

// 🔥 图二/图三：保留换行的原始 realmSystem（供品阶成对文武对照注入，避免被压成单行→）
function getRealmSystemRawFromCenter(sysTypeName: string): string {
  if (!sysTypeName) return ''
  const types = loadSettingTypesFromCenter()
  const found = types.systemTypes.find((t) => t.name === sysTypeName)
  if (!found?.realmSystem) return ''
  return String(found.realmSystem).replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim()
}

// 根据体系类型名称从设定中心获取 description
function getSystemDescriptionFromCenter(sysTypeName: string): string {
  if (!sysTypeName) return ''
  const types = loadSettingTypesFromCenter()
  const found = types.systemTypes.find((t) => t.name === sysTypeName)
  return found?.description || ''
}

// 根据金手指类型名称从设定中心获取详细字段
// 字段迁移：specificAbilities → triggerCondition（语义重新定义为"触发条件"）
function getAbilityDetailFromCenter(abilityTypeName: string): { coreFunction: string; triggerCondition: string; limitations: string; growthPath: string } {
  if (!abilityTypeName) return { coreFunction: '', triggerCondition: '', limitations: '', growthPath: '' }
  const types = loadSettingTypesFromCenter()
  const found = types.abilityTypes.find((t) => t.name === abilityTypeName)
  return {
    coreFunction: found?.coreFunction || '',
    // 兼容字段迁移：优先 triggerCondition，回退 specificAbilities
    triggerCondition: found?.triggerCondition || found?.specificAbilities || '',
    limitations: found?.limitations || '',
    growthPath: found?.growthPath || '',
  }
}

// 根据体系类型名称从设定中心获取修炼方式
function getCultivationMethodFromCenter(sysTypeName: string): string {
  if (!sysTypeName) return ''
  const types = loadSettingTypesFromCenter()
  const found = types.systemTypes.find((t) => t.name === sysTypeName)
  return found?.cultivationMethod || ''
}

// 根据体系类型名称从设定中心获取克制关系
function getRestraintRelationFromCenter(sysTypeName: string): string {
  if (!sysTypeName) return ''
  const types = loadSettingTypesFromCenter()
  const found = types.systemTypes.find((t) => t.name === sysTypeName)
  return found?.restraintRelation || ''
}

async function checkVipPermission(novelId?: string): Promise<{ allowed: boolean; message: string }> {
  const metadata = loadUserMetadata()
  
  // 优先从 Prisma 数据库检查 VIP 状态（微信支付回调写入的权威数据源）
  try {
    const vipUsers = await prisma.user.findMany({
      where: { subscriptionTier: 'pro' },
      select: { id: true, subscriptionExpiresAt: true }
    })
    const now = new Date()
    const activeVip = vipUsers.find(u => {
      if (!u.subscriptionExpiresAt) return true
      return new Date(u.subscriptionExpiresAt) > now
    })
    if (activeVip) {
      return { allowed: true, message: 'VIP会员' }
    }
  } catch (e) {
    // 数据库查询失败时回退到本地文件检查
    console.warn('[ai-generate] Prisma VIP检查失败，回退到本地文件:', e instanceof Error ? e.message : String(e))
  }
  
  // 回退：本地 JSON 文件检查（兼容旧数据）
  if (metadata.vipStatus === 'vip') {
    return { allowed: true, message: 'VIP会员' }
  }
  
  if (metadata.totalGeneratedCount === 0) {
    if (novelId) {
      metadata.firstGeneratedNovelId = novelId
      metadata.totalGeneratedCount = 1
      if (!metadata.createdNovelIds.includes(novelId)) {
        metadata.createdNovelIds.push(novelId)
      }
      saveUserMetadata(metadata)
    }
    return { allowed: true, message: '免费用户第1本作品' }
  }
  
  if (metadata.totalGeneratedCount === 1) {
    if (novelId && novelId === metadata.firstGeneratedNovelId) {
      return { allowed: true, message: '免费用户第1本作品（续生成）' }
    }
    
    if (!metadata.firstGeneratedNovelId && novelId) {
      metadata.firstGeneratedNovelId = novelId
      if (!metadata.createdNovelIds.includes(novelId)) {
        metadata.createdNovelIds.push(novelId)
      }
      saveUserMetadata(metadata)
      return { allowed: true, message: '免费用户第1本作品' }
    }
  }
  
  return { allowed: false, message: '需要开通VIP会员才能生成第2本及以上作品' }
}

const promptCache: Record<string, string> = {}

function getCachedPrompt(key: string, builder: () => string): string {
  if (!promptCache[key]) {
    promptCache[key] = builder()
  }
  return promptCache[key]
}

// ============ Utility: Clean nested JSON strings ============
function cleanJsonField(value: any): string {
  if (!value) return ''
  
  if (typeof value === 'object' && value !== null) {
    if (Array.isArray(value)) {
      return value
        .map((item: any, index: number) => {
          if (typeof item === 'object' && item !== null) {
            if (item.timeline && item.event) {
              return `${item.timeline}·${item.event}`
            } else if (item.region && item.features) {
              return `${item.region}: ${item.features}`
            } else if (item.level && item.description) {
              return `${item.level}: ${item.description}`
            }
            return Object.values(item).filter(function(v: any) { return typeof v === 'string' }).join(', ')
          }
          return String(item)
        }).join(', ')
    } else {
      return Object.entries(value).map(function([key, val]: [string, any]) {
        if (Array.isArray(val)) {
          return `${key}: ${val.join(', ')}`
        } else if (typeof val === 'object' && val !== null) {
          return `${key}: ${Object.values(val).filter(function(v: any) { return typeof v === 'string' }).join(', ')}`
        }
        return `${key}: ${val}`
      }).join('; ')
    }
  }
  
  return String(value)
}

var PROTO_POLLUTION_KEYS = ['constructor', 'hasOwnProperty', 'isPrototypeOf', 'propertyIsEnumerable', 'toLocaleString', 'toString', 'valueOf', '__proto__', '__defineGetter__', '__defineSetter__', '__lookupGetter__', '__lookupSetter__']

var PLACEHOLDER_VALUES = [
  'None', 'none', 'N/A', 'unknown', '未知', '暂无',
  '占位符', '缺失', '请填写', '待补充', '填写',
  'Not specified', 'not specified', 'TBD', 'tbd',
  'AI未生成', 'ai未生成',
  'xxx', 'xxx'
]

var chineseChars = [
  '\u4e00', '\u4e01', '\u4e02', '\u4e03', '\u4e04', '\u4e05', '\u4e06', '\u4e07', '\u4e08', '\u4e09'
]

function isPlaceholder(val: any): boolean {
  if (typeof val !== 'string') return false
  var trimmed = val.trim()
  if (trimmed.length === 0) return true
  for (var _p = 0; _p < PLACEHOLDER_VALUES.length; _p++) {
    var pv = PLACEHOLDER_VALUES[_p]
    if (trimmed === pv) return true
    // Only check startsWith for multi-character placeholders to avoid false-positives
    // e.g. " should not match "无上至尊", "未知" should not match "未知力量"
    if (pv.length >= 2 && trimmed.indexOf(pv) === 0) return true
  }
  if (!chineseChars || chineseChars.length === 0) {
    if (trimmed.length <= 3) return true
    if (/^[a-zA-Z0-9\s_]+$/.test(trimmed) && trimmed.length < 20) return true
  }
  return false
}

// Schema echo patterns: detect when AI echoes back schema description text instead of real content
var SCHEMA_ECHO_PATTERNS = [
  '在此处填写', '时代背景', '地理环境', '历史背景', '力量体系', '社会结构',
  '科技/修炼', '修炼水平', '核心世界规则', '核心卖点', '一句话简介',
  '剧情节点名称', '分卷名称', '搜索关键词', '分类标签', '封面风格',
  '配色方案', '布局设计', '核心视觉元素', 'AI绘画提示语',
  '明确时间节点', '描述主要大陆', '描述当前时代', '说明等级划分',
  '描述主要势力', '明确当前时代', '剧情概要', '发生地点',
  '本剧情的起点', '对后续剧情', '对剧情发展的',
  '所在章节范围', '主要参与人物',
]

function stripSchemaEcho(val: string): string {
  if (!val || typeof val !== 'string') return ''
  var trimmed = val.trim()
  if (trimmed === 'N/A' || trimmed === 'null' || trimmed === 'undefined' || trimmed === 'none') return ''
  // 纯模板占位（无后续实际内容）才整体清空
  if (/^(在此处填写|请填写|待补充|占位符)\s*[:：]?\s*$/.test(trimmed)) return ''
  // 🔥 增强：检测"基于本作XX设定填写..."这类AI提示占位符文本
  if (/^基于本作[\u4e00-\u9fa5]{0,20}设定填写/.test(trimmed)) return ''
  if (/^基于前序[\u4e00-\u9fa5]{0,20}(?:设定|内容)填写/.test(trimmed)) return ''
  if (/填写[\u4e00-\u9fa5]{0,30}(?:建议|内容|信息|描述|字段)/.test(trimmed) && trimmed.length < 80) return ''
  if (/建议\d+-\d+字/.test(trimmed) && trimmed.length < 60) return ''
  if (/^暂无[\u4e00-\u9fa5]{0,10}，/.test(trimmed) && trimmed.length < 50) return ''
  // 字段标签前缀：AI 常按 "时代背景：xxx" 格式回写，仅剥离标签前缀，保留后续真实内容
  // 否则把整条 era/geography 清空，会导致前端 isEmptyResult 误判为"空结果"
  var LABEL_PREFIXES = [
    '时代背景', '地理环境', '历史背景', '力量体系', '社会结构',
    '科技/修炼', '修炼水平', '核心世界规则', '核心卖点', '一句话简介',
    '剧情节点名称', '分卷名称', '搜索关键词', '分类标签', '封面风格',
    '配色方案', '布局设计', '核心视觉元素', 'AI绘画提示语',
    '明确时间节点', '描述主要大陆', '描述当前时代', '说明等级划分',
    '描述主要势力', '明确当前时代', '剧情概要', '发生地点',
    '本剧情的起点', '对后续剧情', '对剧情发展的',
    '所在章节范围', '主要参与人物',
  ]
  for (var _se = 0; _se < LABEL_PREFIXES.length; _se++) {
    var prefix = LABEL_PREFIXES[_se]
    if (trimmed.indexOf(prefix) === 0) {
      var afterLabel = trimmed.substring(prefix.length).replace(/^[\s:：、,，\-—·]+/, '')
      // 剥离前缀后若仍有实际内容，则保留；否则视为纯 schema 回写，返回空
      if (afterLabel.length >= 2) return afterLabel
      return ''
    }
  }
  // 白名单：角色职位等已知短值不算 schema 回写
  var ROLE_WHITELIST = ['主角', '女主', '反派', '忠仆', '挚友', '中立', '男', '女', 'protagonist', 'heroine', 'villain', 'ally', 'neutral', 'male', 'female']
  if (ROLE_WHITELIST.indexOf(trimmed) !== -1) return val
  // 短文本且明显为占位模板时清空
  var meaningful = trimmed.replace(/[0-9\-\u4e00-\u9fa5,、。\s]/g, '')
  if (meaningful.length <= 3) {
    var isRealSchemaEcho = /填写|可选|示例|如示例|占位|模板|在此处|以上|以下|默认/.test(trimmed)
    if (isRealSchemaEcho) return ''
  }
  return val
}

function fixPunctuation(text: string): string {
  if (!text || typeof text !== 'string') return text
  var result = text
  // 0. 先替换英文标点为中文标点（在中文语境下）
  result = result.replace(/([\u4e00-\u9fa5])\.([\u4e00-\u9fa5\s])/g, '$1。$2')
  result = result.replace(/([\u4e00-\u9fa5]),([\u4e00-\u9fa5\s])/g, '$1，$2')
  result = result.replace(/([\u4e00-\u9fa5])\?([\u4e00-\u9fa5\s])/g, '$1？$2')
  result = result.replace(/([\u4e00-\u9fa5])!([\u4e00-\u9fa5\s])/g, '$1！$2')
  result = result.replace(/([\u4e00-\u9fa5]):([\u4e00-\u9fa5\s])/g, '$1：$2')
  result = result.replace(/([\u4e00-\u9fa5]);([\u4e00-\u9fa5\s])/g, '$1；$2')
  // 1. 移除重复标点：。。→。 ！！！→！ ？？→？ ，，→， ；；→； ：：→
  result = result.replace(/([。！？，；：])\1+/g, '$1')
  // 1b. 不同标点连续出现时取最后一个（例如"。，"→"，"，"！。"→"。"）
  result = result.replace(/[。！？，；：]{2,}/g, function(m) { return m.charAt(m.length - 1) })
  // 2. 重复省略号修正：………→……
  result = result.replace(/…{3,}/g, '……')
  // 2b. 连续英文句号... → ……
  result = result.replace(/\.{3,}/g, '……')
  // 2c. 半角句号 → 全角句号（中文句末/句间；中文否定回顾，避免误伤小数 3.14 / 英文缩写）
  result = result.replace(/(?<=[一-龥】」』”’。！？，、；：…—）])\.(?=\s*[一-龥]|\s*$)/g, '。')
  // 2d. 清理误生成的双重标点（，。/ 。。 等）
  result = result.replace(/[，。]+\s*[。]/g, '。')
  result = result.replace(/[。]{2,}/g, '。')
  // 3. 中文句子末尾缺少句号：如果字符串以中文结尾（非标点、非引号、非换行），补充句号
  // 跳过标题类短文本（<=10字且不含句中停顿），只处理>15字的段落
  var _trimmed = result.trim()
  if (_trimmed.length > 15 && /[\u4e00-\u9fa5]$/.test(_trimmed) && !/[。！？…：”"）】》]$/.test(_trimmed)) {
    result = _trimmed + '。'
  } else if (_trimmed.length > 15 && /[，；：、]$/.test(_trimmed)) {
    // 句末出现句中标点（，；：、）时，替换为。
    result = _trimmed.slice(0, -1) + '。'
  }
  // 4. 清理多个连续空格
  result = result.replace(/[ \t]{2,}/g, ' ')
  return result
}

function cleanStructuredData(obj: any): any {
  if (!obj || typeof obj !== 'object') return Array.isArray(obj) ? [] : {}
  if (Array.isArray(obj)) {
    return obj
      .filter(function(item: any) { return item !== null && item !== undefined && item !== '' && !(Array.isArray(item) && item.length === 0) && (typeof item !== 'string' || !isPlaceholder(item)) })
      .map(function(item: any) {
        if (typeof item === 'object' && item !== null) return cleanStructuredData(item)
        if (typeof item === 'string') return fixPunctuation(item)
        return item
      })
  }
  var cleanObj: any = {}
  for (var _i = 0, _keys = Object.keys(obj), _len = _keys.length; _i < _len; _i++) {
    var key = _keys[_i]
    if (PROTO_POLLUTION_KEYS.indexOf(key) !== -1) continue
    // 🔥 2026-08-22 修复：LLM 输出的键名可能带前导/尾随换行、空白或控制字符（如 "\nworldPowerSystem"），
    //    导致下游 obj.worldPowerSystem 访问落空、字段空值。统一裁剪键名两侧的空白与控制字符。
    var _normKey = String(key).replace(/^[\s\uFEFF\x00-\x1F]+|[\s\uFEFF\x00-\x1F]+$/g, '')
    if (_normKey && _normKey !== key && !Object.prototype.hasOwnProperty.call(cleanObj, _normKey)) {
      key = _normKey
    }
    var value = obj[key]
    if (value === null || value === undefined) continue
    if (Array.isArray(value) && value.length === 0) continue
    if (typeof value === 'string' && isPlaceholder(value)) continue
    if (typeof value === 'object' && !Array.isArray(value)) {
      var nested = cleanStructuredData(value)
      if (Object.keys(nested).length > 0 || key === 'protagonistAbility' || key === 'worldPowerSystem') {
        if (key === 'protagonistAbility' || key === 'worldPowerSystem') {
          cleanObj[key] = nested
        } else {
          if (Object.keys(nested).length > 0) cleanObj[key] = nested
        }
      }
    } else if (Array.isArray(value)) {
      var filteredArr = value.filter(function(item: any) { return item !== null && item !== undefined && item !== '' && (typeof item !== 'string' || !isPlaceholder(item)) }).map(function(item: any) {
        if (typeof item === 'object' && item !== null) return cleanStructuredData(item)
        if (typeof item === 'string') return fixPunctuation(item)
        return item
      })
      if (filteredArr.length > 0) cleanObj[key] = filteredArr
    } else {
      cleanObj[key] = typeof value === 'string' ? fixPunctuation(value) : value
    }
  }
  return cleanObj
}

function validateCoreFields(data: any, requiredFields: string[], stepName: string): string | null {
  for (var _j = 0; _j < requiredFields.length; _j++) {
    var f = requiredFields[_j]
    if (f.indexOf('|') !== -1) {
      var alternatives = f.split('|')
      var anyValid = false
      for (var _a = 0; _a < alternatives.length; _a++) {
        var alt = alternatives[_a].trim()
        var val = data[alt]
        if (val !== undefined && val !== null && val !== '' && (typeof val !== 'string' || !isPlaceholder(val))) {
          if (typeof val !== 'string' || val.trim() !== '') {
            if (!Array.isArray(val) || val.length > 0) {
              anyValid = true
              break
            }
          }
        }
      }
      if (!anyValid) return '[' + stepName + ' missing required field: ' + f
      continue
    }
    var val2 = data[f]
    if (val2 === undefined || val2 === null) return '[' + stepName + ' missing required field: ' + f
    if (typeof val2 === 'string' && isPlaceholder(val2)) return '[' + stepName + ' required field ' + f + ' is placeholder'
    if (typeof val2 === 'string' && val2.trim() === '') return '[' + stepName + ' required field ' + f + ' is empty'
    if (Array.isArray(val2) && val2.length === 0) return '[' + stepName + ' required field ' + f + ' is empty array'
  }
  return null
}

