// 后置校验与自动修复工具函数
// ============================================================

// 统计中文字符数
function countZhChars(s: string): number {
  if (!s) return 0
  var m = s.match(/[\u4e00-\u9fa5]/g)
  return m ? m.length : 0
}

// 清理卷摘要套话
function cleanCliches(text: string): string {
  if (!text) return text
  var result = text
  var cliches = [
    /开篇[,，]?/g,
    /开卷[,，]?/g,
    /[,，]?构成了本卷波澜壮阔的篇章/g,
    /[,，]?也为下一卷的全面爆发埋下了伏笔/g,
    /[,，]?为下一卷?埋下了伏笔/g,
    /[,，]?为后续剧情埋下伏笔/g,
    /[,，]?拉开了序幕/g,
    /[,，]?吹响了.*号角/g,
    /[,，]?承上启下[,，]?/g,
    /实力、人脉、势力格局均发生不可逆变化/g,
    /实力人脉势力格局均发生不可逆变化/g,
    /发生不可逆的变化/g,
    /不可逆变化/g,
    /波澜壮阔/g,
    /精彩纷呈/g,
    /好戏才刚刚开始/g,
    /更大的危机悄然降临/g,
    /前路暗藏凶险/g,
    /故事才刚刚开始/g,
    /每一次危机都成为他成长的垫脚石/g,
    /实力与眼界都迈上了新台阶/g,
    /本卷末他站在了新的起点上/g,
    /【悬念】/g,
    /[。，]的高潮/g,
    /的高潮/g,
  ]
  cliches.forEach(function(pat) {
    result = result.replace(pat, '')
  })
  result = result.replace(/[，。]{2,}/g, '。').replace(/^[，。、\s]+/, '').replace(/[，、\s]+$/, '。')
  return result
}

// 句子截断检测与补全：确保文本以完整句子结尾，清理双标点
function ensureCompleteSentence(text: string, maxLen: number): string {
  if (!text) return ''
  var s = String(text).trim()
  if (s.length > maxLen) {
    s = s.slice(0, maxLen)
    var lastPunc = Math.max(s.lastIndexOf('。'), s.lastIndexOf('！'), s.lastIndexOf('？'), s.lastIndexOf('；'))
    if (lastPunc > maxLen * 0.4) {
      s = s.slice(0, lastPunc + 1)
    } else {
      s = s.replace(/[，、；：""''（）\s]+$/, '') + '。'
    }
  }
  if (!/[。！？；]$/.test(s)) s += '。'
  s = s.replace(/。+/g, '。').replace(/，。/g, '。').replace(/、。/g, '。').replace(/：。/g, '：').replace(/\s+。/g, '。').replace(/。，/g, '。')
  return s
}

// 清洗角色名，移除描述性文本（如"的四大战神"、"铁腕手段整顿"等）
function cleanCharacterName(rawName: string, genreType: string): string {
  if (!rawName || typeof rawName !== 'string') return rawName
  var name = String(rawName).trim()
  // 移除名字中"的"之后的所有描述性内容（西幻名·姓格式中，"·"后面是姓氏，不应该有"的"）
  var dePos = name.indexOf('的')
  if (dePos > 1) {
    // 检查"的"前面是否是合理的姓氏/名字结尾（避免误删正常内容）
    var beforeDe = name.substring(0, dePos).trim()
    var afterDe = name.substring(dePos + 1).trim()
    // 如果"的"后面有较长的描述文本，或包含战神/长老/家主/整顿等身份词，截断
    if (afterDe.length > 2 || /战神|长老|家主|族长|整顿|首领|统领|大师|圣女|教皇|王子|公主|公爵|伯爵/.test(afterDe)) {
      name = beforeDe
    }
  }
  // 处理西幻姓名中的"·"分隔：确保每段都是纯名字，不含描述
  var dotParts = name.split('·').filter(Boolean)
  if (dotParts.length > 1) {
    var cleanedParts: string[] = []
    for (var i = 0; i < dotParts.length; i++) {
      var part = dotParts[i].trim()
      // 过滤掉包含动词/身份描述的部分（西幻名字中间名/姓氏应该是纯名词）
      if (part.length > 4 && /手段|整顿|战神|统领|首席|大师|圣女|教皇|王子|公主/.test(part)) {
        break
      }
      // 处理"冯·"、"德·"、"范·"等中间名前缀
      if (i > 0 && /^(冯|德|范|堂|von|de|van)$/i.test(part) && cleanedParts.length > 0) {
        cleanedParts.push(part)
        continue
      }
      cleanedParts.push(part)
    }
    name = cleanedParts.join('·')
  }
  // 中式姓名：限制长度，超过的截断（只保留开头的纯名字）
  // 🔥 修复：洪荒/封神/神话题材名字可以更长（如"玉皇大帝""太乙真人""三太子"等）
  var isWestern = /magic|western|fantasy|西幻|奇幻|魔法|斗气|骑士|教廷|法师|精灵|矮人|巨龙/.test(genreType)
  var isHonghuang = /洪荒|封神榜|封神演义|封神之战|封神量劫|巫族|天庭|阐教|截教|西游/.test(genreType)
  var maxNameLen = isHonghuang ? 6 : 4
  if (!isWestern && name.length > maxNameLen && name.indexOf('·') === -1) {
    // 尝试匹配开头的名字（洪荒题材最多6字，其他题材最多4字）
    var cnNameMatch = name.match(new RegExp('^[\\u4e00-\\u9fa5]{2,' + maxNameLen + '}'))
    if (cnNameMatch) {
      name = cnNameMatch[0]
    }
  }
  return name.trim()
}

// 检查并修复所有角色的姓氏一致性（重写为安全版本：只清洗不强行修改）
function fixSurnameConsistency(characters: any, genreType: string): any {
  if (!characters) return characters
  try {
    var allCharsToCheck: any[] = []
    if (characters.protagonist) allCharsToCheck.push(characters.protagonist)
    if (characters.femaleLead) allCharsToCheck.push(characters.femaleLead)
    if (Array.isArray(characters.femaleLeads)) allCharsToCheck = allCharsToCheck.concat(characters.femaleLeads)
    if (characters.antagonist) allCharsToCheck.push(characters.antagonist)
    if (Array.isArray(characters.antagonists)) allCharsToCheck = allCharsToCheck.concat(characters.antagonists)
    if (Array.isArray(characters.supporting)) allCharsToCheck = allCharsToCheck.concat(characters.supporting)
    if (Array.isArray(characters.masters)) allCharsToCheck = allCharsToCheck.concat(characters.masters)
    if (Array.isArray(characters.allies)) allCharsToCheck = allCharsToCheck.concat(characters.allies)

    for (var ci = 0; ci < allCharsToCheck.length; ci++) {
      var ch = allCharsToCheck[ci]
      if (!ch || !ch.name) continue
      
      // 第一步：清洗名字，移除描述性文本
      var originalName = String(ch.name || '').trim()
      var cleanedName = cleanCharacterName(originalName, genreType)
      if (cleanedName !== originalName) {
        console.log('[post-check] 清洗角色名: "' + originalName + '" -> "' + cleanedName + '"')
        ch.name = cleanedName
      }
      
      var name = String(ch.name || '').trim()
      if (!name || name.length < 2) continue
      
      // 第二步：收集家族信息（只做日志警告，不自动修改姓氏）
      var textToCheck = ''
      if (ch.identity) textToCheck += ' ' + String(ch.identity)
      if (ch.background) textToCheck += ' ' + String(ch.background)
      if (!textToCheck) continue

      var familyPatterns = [
        /([\u4e00-\u9fa5]{2,4})(家族|世家|门阀|氏族)/,
        /出身([\u4e00-\u9fa5]{2,4})(家|家族|氏)/,
        /来自([\u4e00-\u9fa5]{2,4})(家|家族|氏)/,
        /([\u4e00-\u9fa5]{2,4})(家|家族|氏)的(后裔|子弟|传人|后代|子孙|公子|小姐|少爷)/
      ]
      
      var familyName = ''
      for (var pi = 0; pi < familyPatterns.length; pi++) {
        var match = textToCheck.match(familyPatterns[pi])
        if (match) {
          familyName = match[1]
          // 排除常见误匹配词（如"四大"、"铁腕"等不是家族名的词）
          var invalidFamilyWords = ['四大', '铁腕', '手段', '神圣', '光明', '黑暗', '暗影', '魔法', '斗气', '骑士', '教廷', '学院', '帝国', '王国', '联盟', '议会', '神殿', '教会']
          var isInvalid = false
          for (var ii = 0; ii < invalidFamilyWords.length; ii++) {
            if (familyName.indexOf(invalidFamilyWords[ii]) !== -1) {
              isInvalid = true
              break
            }
          }
          if (isInvalid) {
            familyName = ''
            continue
          }
          break
        }
      }

      if (familyName && familyName.length >= 2 && familyName.length <= 4) {
        var dotParts = name.split('·').filter(Boolean)
        if (dotParts.length >= 2) {
          var surname = dotParts[dotParts.length - 1].trim()
          if (surname.length <= 2 && dotParts.length >= 3) {
            surname = dotParts[dotParts.length - 2].trim() + '·' + dotParts[dotParts.length - 1].trim()
          }
          if (surname && surname !== familyName && familyName.length > 0) {
            console.log('[post-check] 注意：角色姓氏可能不一致：角色="' + name + '", 文本中家族="' + familyName + '", 当前姓氏="' + surname + '" (不自动修改，如需修改请手动调整)')
          }
        }
      }
    }
  } catch(e) {
    console.log('[post-check] 角色名清洗/姓氏检查出错:', e)
  }
  return characters
}

