// 递归扫描对象，对字符串字段应用清洗规则
// 注意：跳过 title 字段（书名/章节标题可能是用户原创，不应清洗）
// 跳过 protagonistName 字段（人名不清洗）
function _cleanHonghuangTermsDeep(obj: any, path: string, skipFields: Set<string>): number {
  if (!obj || typeof obj !== 'object') return 0
  var cleaned = 0
  if (Array.isArray(obj)) {
    for (var i = 0; i < obj.length; i++) {
      cleaned += _cleanHonghuangTermsDeep(obj[i], path + '[' + i + ']', skipFields)
    }
  } else {
    for (var k in obj) {
      if (!Object.prototype.hasOwnProperty.call(obj, k)) continue
      var childPath = path ? path + '.' + k : k
      // 跳过指定字段（如title/protagonistName）
      if (skipFields.has(k)) continue
      var v = obj[k]
      if (typeof v === 'string' && v.length > 0) {
        var orig = v
        for (var r = 0; r < _globalHonghuangReplacements.length; r++) {
          var re = _globalHonghuangReplacements[r][0]
          var rep = _globalHonghuangReplacements[r][1]
          v = v.replace(re, rep)
        }
        if (v !== orig) {
          obj[k] = v
          cleaned++
          if (cleaned <= 5) {
            console.log('[globalClean] ' + childPath + ' 字段清洗洪荒词汇')
          }
        }
      } else if (v && typeof v === 'object') {
        cleaned += _cleanHonghuangTermsDeep(v, childPath, skipFields)
      }
    }
  }
  return cleaned
}

