    // 🔥 根据金手指名称推断正确的金手指类型
function inferAbilityTypeFromName(name: string): string {
  if (!name || typeof name !== 'string') return ''
  var n = name.trim()
  console.log('[inferAbilityTypeFromName] 输入名称: "' + n + '"')
  // 功法类关键词：真经、功法、诀、术、法、经、典、录、卷、秘籍、秘典、心法
  if (/真经|功法|诀|秘术|心法|秘籍|秘典|宝典|仙法|神功|天书|玄功/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 功法类'); return '功法类' }
  // 血脉类关键词：血、脉、体、骨、祖、巫(巫族相关)
  if (/血脉|圣体|神体|魔体|仙体|道体|霸体|战体|巫体|祖血|神血|圣血/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 血脉类'); return '血脉类' }
  // 系统类关键词：系统、面板、商城、签到、抽奖
  if (/系统|面板|商城|签到|抽奖|任务|辅助/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 系统类'); return '系统类' }
  // 神器类关键词：神器、宝、兵、器、剑、刀、枪、鼎、炉、塔、印、珠、环、镜、戒
  if (/神器|至宝|神兵|仙器|魔器|圣器|宝塔|神鼎|灵珠|宝镜|神剑|魔刀|仙枪|灵环|祖塔|神塔|巫塔|戒指|戒/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 神器类'); return '神器类' }
  // 天赋类关键词：天赋、异禀、体质、灵根、慧根、天眼、神瞳、圣瞳
  if (/天赋|异禀|体质|灵根|慧根|天眼|神瞳|圣瞳|灵体|仙资/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 天赋类'); return '天赋类' }
  // 灵魂类关键词：灵魂、魂、灵、元神、神识、精神力
  if (/灵魂|神魂|元神|神识|灵魄|双魂|魂环|魂印|灵识/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 灵魂类'); return '灵魂类' }
  // 空间类关键词：空间、戒、界、洞天、小世界、秘境、储物
  if (/空间|洞天|小世界|秘境|储物|乾坤|须弥|芥子|随身/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 空间类'); return '空间类' }
  // 时间类关键词：时间、回溯、预知、重生、轮回、逆转
  if (/时间|回溯|预知|轮回|逆转|时光|穿梭|重启/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 时间类'); return '时间类' }
  // 契约类关键词：契约、御兽、召唤、式神、宠物
  if (/契约|御兽|召唤|式神|宠物|灵兽|魔兽|神兽|妖兽/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 契约类'); return '契约类' }
  // 吞噬类关键词：吞噬、掠夺、吸收、融合、进化
  if (/吞噬|掠夺|融合|进化|吸收|吞天/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 吞噬类'); return '吞噬类' }
  // 领域类关键词：领域、法则、秩序、规则、结界
  if (/领域|法则|秩序|规则|结界|禁制/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 领域类'); return '领域类' }
  // 知识类关键词：记忆、知识、智谋、通鉴、经略、兵法
  if (/记忆|知识|智谋|通鉴|经略|兵法|华夏|传承|学识/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 知识类'); return '知识类' }
  // 异能类关键词：异能、超能力、念力、透视、读心
  if (/异能|超能力|念力|透视|读心|控火|控水|控雷|念动力/.test(n)) { console.log('[inferAbilityTypeFromName] 匹配: 异能类'); return '异能类' }
  console.log('[inferAbilityTypeFromName] 无匹配，返回空字符串')
  return ''
}

// 🔥 2026-08-31：由金手指类型(protagonistAbility.type)推导对应的"世界力量体系类型"(worldPowerSystem.type)。
//    两者属不同分类体系，此处建立对应映射，确保"世界观力量体系取值于金手指/体系类型"且双向同步。
function _deriveWorldSystemType(abilityType: string, genre: string): string {
  if (!abilityType) return ''
  var at = String(abilityType).trim()
  var g = String(genre || '').toLowerCase()
  var isXian = /cultivation|xuanhuan|修|玄|仙|武道|洪荒|神话/.test(g)
  var isWestern = /western|西幻|魔法|奇幻|魔幻/.test(g)
  var isHistory = /history|历史|朝堂|架空|权谋|古代/.test(g)
  var isScifi = /scifi|科幻|星际|末世|机甲|赛博/.test(g)
  var map: Record<string, string> = {
    '系统类': '系统流体系',
    '功法类': isXian ? '修仙体系' : '武道体系',
    '血脉类': isXian ? '妖族体系' : '血脉体系',
    '神器类': isXian ? '神道体系' : '神器体系',
    '天赋类': '天赋体系',
    '灵魂类': '魂修体系',
    '空间类': '空间体系',
    '时间类': '时间体系',
    '轮回类': '轮回体系',
    '契约类': '契约体系',
    '吞噬类': '吞噬进化体系',
    '领域类': '领域体系',
    '知识类': isHistory ? '朝堂权力体系' : '知识文明体系',
    '记忆类': isHistory ? '朝堂权力体系' : '知识文明体系',
    '智谋类': isHistory ? '朝堂权力体系' : '权谋谋略体系',
    '异能类': '异能等级体系',
    '气运类': '气运体系',
    '无金手指': '无等级体系',
  }
  return map[at] || (isWestern ? '魔法体系' : (isHistory ? '朝堂权力体系' : (isScifi ? '科技进化体系' : '修炼体系')))
}

function splitGoldenFingerNames(systemName: string): string[] {
  if (!systemName || typeof systemName !== 'string') return []
  var cleaned = systemName.trim()
  if (!cleaned || cleaned === '无' || cleaned === '无金手指' || cleaned === '无系统') return []
  var parts = cleaned.split(/\s*(?:与|和|、|及|\+|,|，|双金手指|双重|两个)\s*/).filter(function(p: string) {
    return p && p.trim().length >= 2 && !/^(金手指|系统|双重|两个|觉醒)$/.test(p.trim())
  })
  return parts.map(function(p) { return p.trim() }).filter(function(p) { return p.length >= 2 })
}

