      const volNum = previousData?.targetVolume || previousData?.currentVolume || 1
      const batchStart = previousData?.chapterBatchStart || previousData?.batchStart || 1
      const batchEnd = previousData?.chapterBatchEnd || (batchStart + 1)
      const batchCount = Math.max(1, batchEnd - batchStart + 1)
