      var scanMatches = function(text: string, words: string[], max: number): string[] {
        if (!text || text.length < 2) return []
        var result: string[] = []
        var seen = new Set<string>()
        for (var wi2 = 0; wi2 < words.length; wi2++) {
          if (result.length >= max) break
          var w2 = words[wi2]
          if (!w2 || w2.length < 2) continue
          if (seen.has(w2)) continue
          if (text.indexOf(w2) !== -1) { seen.add(w2); result.push(w2) }
        }
        return result
      }

      var extractSemanticFingerprints = function(text: string): string[] {
        if (!text || text.length < 5) return []
        var fingerprints: string[] = []
        var seen = new Set<string>()
        var addUnique = function(w: string) { if (!w || w.length < 2 || seen.has(w)) return; seen.add(w); fingerprints.push(w) }
        var pMatches = scanMatches(text, SEMANTIC_PLACES, 3)
        for (var pi2 = 0; pi2 < pMatches.length; pi2++) addUnique(pMatches[pi2])
        var iMatches = scanMatches(text, SEMANTIC_ITEMS, 3)
        for (var ii2 = 0; ii2 < iMatches.length; ii2++) addUnique(iMatches[ii2])
        var eMatches = scanMatches(text, SEMANTIC_ENEMIES, 2)
        for (var ei2 = 0; ei2 < eMatches.length; ei2++) addUnique(eMatches[ei2])
        var sMatches = scanMatches(text, SEMANTIC_SPECIALS, 2)
        for (var si2 = 0; si2 < sMatches.length; si2++) addUnique(sMatches[si2])
        var aMatches = scanMatches(text, SEMANTIC_ACTIONS, 2)
        for (var ai2 = 0; ai2 < aMatches.length; ai2++) addUnique(aMatches[ai2])
        return fingerprints
      }

