      function _textSim(a: string, b: string): number {
        if (!a || !b) return 0
        var la = a.length, lb = b.length
        if (la === 0 || lb === 0) return 0
        var minLen = Math.min(la, lb)
        var common = 0
        for (var _si = 0; _si < la - 3; _si++) {
          if (b.indexOf(a.substring(_si, _si + 4)) !== -1) common += 4
        }
        return common / minLen
      }

