    var _JSON_STEPS = ['idea', 'worldbuilding', 'powerSystem', 'characters', 'factions', 'relationships', 'outline', 'synopsis', 'keyPlots', 'chapters']
    // 🔥 2026-08-11 实测迭代版映射。
